mapper.select:
select au.nickname as authorName ,apdr.* from author_private_data_report apdr
left join(
    select id, author_source,nickname from author_user
)au on apdr.author_id = au.id


        and author_id = #{reqVO.authorId}


        and `date` between #{reqVO.startTime} and #{reqVO.endTime}


        and author_id in

            #{item}



        and au.author_source = #{reqVO.type}


        and apdr.tenant_id = #{reqVO.tenantId}


order by apdr.date desc

SELECT CONCAT(YEAR(apdr.date), '-', WEEK(apdr.date, 1)) AS `date`, CONCAT( DATE_FORMAT(apdr.date, '%Y-%m-%d'), ' ~ ', DATE_FORMAT(DATE_ADD(apdr.date, INTERVAL 6 DAY), '%Y-%m-%d') ) AS dateRange,au.nickname as authorName , (SELECT apdr_last.fans_count FROM author_private_data_report apdr_last WHERE apdr_last.author_id = apdr.author_id AND CONCAT(YEAR(apdr_last.date), '-', WEEK(apdr_last.date, 1)) = CONCAT(YEAR(apdr.date), '-', WEEK(apdr.date, 1)) ORDER BY apdr_last.date DESC LIMIT 1) as fans_count, (SELECT apdr_last.account_fans FROM author_private_data_report apdr_last WHERE apdr_last.author_id = apdr.author_id AND CONCAT(YEAR(apdr_last.date), '-', WEEK(apdr_last.date, 1)) = CONCAT(YEAR(apdr.date), '-', WEEK(apdr.date, 1)) ORDER BY apdr_last.date DESC LIMIT 1) as account_fans, ifnull(sum(apdr.add_fans),0) as authorAddFans, ifnull(sum(apdr.cancel_fans),0) as authorCancelFans, ifnull(sum(apdr.account_add_fans),0) as accountAddFans, ifnull(sum(apdr.account_cancel_fans),0) as accountCancelFans from author_private_data_report apdr left join( select id, author_source,nickname from author_user )au on apdr.author_id = au.id
and author_id = #{reqVO.authorId}
AND CONCAT(YEAR(apdr.date), '-', WEEK(apdr.date, 1)) BETWEEN #{reqVO.startTime} AND #{reqVO.endTime}
and author_id in
#{item}
and au.author_source = #{reqVO.type}
and apdr.tenant_id = #{reqVO.tenantId}
group by apdr.date,apdr.author_id order by apdr.date desc

SELECT DATE_FORMAT(apdr.date, '%Y-%m') AS `date`, au.nickname as authorName , (SELECT apdr_last.fans_count FROM author_private_data_report apdr_last WHERE apdr_last.author_id = apdr.author_id AND DATE_FORMAT(apdr_last.date, '%Y-%m') = DATE_FORMAT(ANY_VALUE(apdr.date), '%Y-%m') ORDER BY apdr_last.date DESC LIMIT 1) as fans_count, (SELECT apdr_last.account_fans FROM author_private_data_report apdr_last WHERE apdr_last.author_id = apdr.author_id AND DATE_FORMAT(apdr_last.date, '%Y-%m') = DATE_FORMAT(ANY_VALUE(apdr.date), '%Y-%m') ORDER BY apdr_last.date DESC LIMIT 1) as account_fans, ifnull(sum(apdr.add_fans),0) as authorAddFans, ifnull(sum(apdr.cancel_fans),0) as authorCancelFans, ifnull(sum(apdr.account_add_fans),0) as accountAddFans, ifnull(sum(apdr.account_cancel_fans),0) as accountCancelFans from author_private_data_report apdr left join( select id, author_source,nickname from author_user )au on apdr.author_id = au.id
and author_id = #{reqVO.authorId}
AND DATE_FORMAT(apdr.date, '%Y-%m') BETWEEN #{reqVO.startTime} AND #{reqVO.endTime}
and author_id in
#{item}
and au.author_source = #{reqVO.type}
and apdr.tenant_id = #{reqVO.tenantId}
group by DATE_FORMAT(apdr.date, '%Y-%m'),apdr.author_id order by apdr.date desc
